'use strict';
const VERSION='1.5', BASE='https://raw.githubusercontent.com/woodsstudiosupport/cloverstoresupports/main/', REPO='https://github.com/woodsstudiosupport/cloverstoresupports';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHTML;
const httpsURL=value=>{try{const u=new URL(String(value));return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}};
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem('clover-html-v5:'+key))??fallback}catch{return fallback}}
function saveLocal(key,value){try{localStorage.setItem('clover-html-v5:'+key,JSON.stringify(value));return true}catch{return false}}
const defaults={theme:'dark',wallpaper:'pure-black',accent:'violet',density:'comfortable',motion:'auto',textSize:'100',concurrency:'1',wifiOnly:false,chargingOnly:false,haptics:false,publicUrl:'',externalWebsites:false,multipleFiles:false};
function arrayLocal(key){const value=readLocal(key,[]);return Array.isArray(value)?value:[]}
const prefs={...defaults,...readLocal('preferences',{})};
const state={tab:'Discover',category:'All',query:'',detail:null,developer:null,collection:null,apps:SEED.registry,reviews:SEED.reviews,developers:SEED.developers,collections:SEED.collections,releases:SEED.releases,announcements:SEED.announcements,manifest:SEED.catalogue,synced:window.CLOVER_BOOT.fetchedAt,syncing:false,loaded:true,error:false,reviewSort:'registry',scope:'All devices',publisher:'All publishers',sort:'Featured',searchKind:'All',favorites:new Set(arrayLocal('favorites').filter(x=>typeof x==='string')),follows:new Set(arrayLocal('follows').filter(x=>typeof x==='string')),recent:arrayLocal('recent').filter(x=>typeof x==='string').slice(0,20),searches:arrayLocal('searches').filter(x=>typeof x==='string').slice(0,10),watch:readLocal('watch',{}),compare:[],channels:{},handoff:arrayLocal('handoff').filter(x=>x&&httpsURL(x.url)).slice(0,50),positions:{},downloads:arrayLocal('downloads').filter(d=>d&&httpsURL(d.url)).map(d=>({...d,status:['Downloading','Ready to save','Checking'].includes(d.status)?'Interrupted':d.status}))};
let timer,toastTimer,detailObserver=null,dbPromise,battery=null,inspection=null,inspectionFile=null,downloadFolder=null,batchSaving=false;
const controllers=new Map(),fileURLs=new Map(),fileBlobs=new Map(),speedSamples=new Map();
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4800)}
function notify(text){toast(text);if('Notification'in window&&Notification.permission==='granted'&&document.hidden){try{new Notification('Clover Store',{body:text,icon:document.querySelector('.store-icon')?.src})}catch{}}}
function haptic(){if(prefs.haptics)navigator.vibrate?.(12)}
function allApps(){return state.apps.filter(a=>a&&String(a.name||'').trim()&&a.id&&a.id!=='null')}
function appById(id){return allApps().find(a=>a.id===id)}
function developerById(id){return state.developers.find(d=>d.id===id)}
function developerFor(a){return developerById(a.developerId)||state.developers.find(d=>(d.legacyNames||[]).includes(a.developer)||d.displayName===a.developer)}
function supplier(a){return (state.manifest.installationPolicy?.supplierDeveloperIds||['woods-studio']).includes(developerFor(a)?.id)}
function packageId(a){return String(a.androidPackageName||a.packageName||a.id||'')}
const validPackage=id=>/^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z][A-Za-z0-9_]*)+$/.test(id);
const PLATFORM_LABELS={windows:'Windows',android:'Android',linux:'Linux',macos:'macOS',ios:'iPhone & iPad',chromeos:'ChromeOS',homeui:'Clover HomeUI','clover-splash':'Clover Splash',web:'Web'};
function detectPlatform(ua=navigator.userAgent,touches=navigator.maxTouchPoints||0){if(/android/i.test(ua))return'android';if(/iphone|ipad|ipod/i.test(ua)||(/macintosh/i.test(ua)&&touches>1))return'ios';if(/cros/i.test(ua))return'chromeos';if(/windows/i.test(ua))return'windows';if(/macintosh|mac os x/i.test(ua))return'macos';if(/linux/i.test(ua))return'linux';return'unknown'}
function platform(){return readLocal('platform','auto')==='auto'?detectPlatform():readLocal('platform','auto')}
function platformLabel(key){return PLATFORM_LABELS[key]||String(key||'Unknown').replace(/[_-]/g,' ')}
function hasAndroid(a){return Boolean(httpsURL(a.downloads?.android)||state.releases.some(r=>r.appId===a.id&&r.platform==='android'))}
function availableDownloads(a,channel=state.channels[a.id]||'stable'){const map=new Map();if(channel==='stable')for(const[key,url]of Object.entries(a.downloads||{})){const safe=httpsURL(url);if(safe)map.set(key,{key,url:safe,version:a.version,versionCode:a.androidVersionCode||a.versionCode,sha256:key==='android'?a.androidSha256:null})}const releases=state.releases.filter(r=>r.appId===a.id&&r.channel===channel&&httpsURL(r.url)).sort((a,b)=>(Number(a.versionCode)||0)-(Number(b.versionCode)||0)||String(a.publishedAt||'').localeCompare(String(b.publishedAt||'')));for(const r of releases)map.set(r.platform,{...r,key:r.platform,url:httpsURL(r.url)});return[...map.values()]}
function primaryDownload(a){return availableDownloads(a).find(d=>d.key===platform())}
function reviewInfo(a){const list=(Array.isArray(state.reviews[a.id])?state.reviews[a.id]:[]).filter(r=>r&&typeof r==='object'),valid=list.filter(r=>Number(r.rating)>=1&&Number(r.rating)<=5);return{list,valid,average:valid.length?valid.reduce((s,r)=>s+Number(r.rating),0)/valid.length:0}}
function stars(n){return'★'.repeat(Math.max(0,Math.min(5,Math.round(Number(n)||0))))+'☆'.repeat(5-Math.max(0,Math.min(5,Math.round(Number(n)||0))))}
function categories(){return[...new Set(allApps().map(a=>a.category||'Other'))]}
function formatBytes(n){if(!Number.isFinite(n)||n<=0)return'Not provided';if(n>=1073741824)return(n/1073741824).toFixed(1)+' GB';if(n>=1048576)return(n/1048576).toFixed(1)+' MB';return Math.ceil(n/1024)+' KB'}
const glyphs={Discover:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5Z"/>',Browse:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',Search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',Library:'<path d="M5 4h14v17l-7-4-7 4Z"/>',Downloads:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',Developers:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',Updates:'<path d="M20 8v5h-5M4 16v-5h5M20 12a8 8 0 0 0-14-5M4 12a8 8 0 0 0 14 5"/>',Compare:'<path d="M7 3v18M17 3v18M3 7h8M13 17h8"/>',Settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3Z"/>',Inspector:'<path d="M4 4h16v16H4Z M9 8l-3 4 3 4m6-8 3 4-3 4"/>'};
function svg(name){return'<svg viewBox="0 0 24 24" aria-hidden="true">'+(glyphs[name]||glyphs.Browse)+'</svg>'}
function button(text,action,extra='',style=''){return'<button class="action '+style+'" data-action="'+action+'" '+extra+'>'+E(text)+'</button>'}
function heading(title,desc){return'<header class="page-heading"><div class="eyebrow">CLOVER STORE / '+E(state.developer?'DEVELOPERS':state.tab.toUpperCase())+'</div><h1>'+E(title)+'</h1><p>'+E(desc)+'</p></header>'}
function message(title,desc){return'<section class="message"><h3>'+E(title)+'</h3><p>'+E(desc)+'</p></section>'}
function section(title,subtitle,action=''){return'<div class="section-top"><div><h2>'+E(title)+'</h2><p>'+E(subtitle)+'</p></div>'+action+'</div>'}
function icon(a,extra=''){return'<span class="icon-wrap '+extra+'"><img class="app-icon" loading="lazy" src="'+E(httpsURL(a.icon))+'" alt="'+E(a.name)+' icon"><span class="icon-fallback" aria-hidden="true">'+E((a.name||'?')[0])+'</span></span>'}
function initials(name){return String(name||'?').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function developerIcon(d){return'<div class="developer-avatar">'+(httpsURL(d?.icon)?'<img loading="lazy" src="'+E(httpsURL(d.icon))+'" alt="'+E(d.displayName)+' icon">':'<span>'+E(initials(d?.displayName))+'</span>')+'</div>'}
function verified(d){return d?.verification?.status==='verified'?'<span class="verified" title="Verified developer">'+svg('Discover')+' Verified</span>':''}
function grid(apps){return'<div class="card-grid">'+apps.map(card).join('')+'</div>'}
function card(a){const d=primaryDownload(a),r=reviewInfo(a),dev=developerFor(a);return'<article class="app-card"><button class="card-main" data-open="'+E(a.id)+'"><div class="card-top">'+icon(a)+'<div class="card-title"><h3>'+E(a.name)+'</h3><p>'+E(dev?.displayName||a.developer||'Independent developer')+'</p></div></div><p class="card-description">'+E(a.description||'Explore this application.')+'</p><div class="card-meta"><span>'+E(a.category||'Apps')+'</span><span>'+(r.average?'★ '+r.average.toFixed(1):'v'+E(a.version||'—'))+'</span></div></button><div class="card-footer"><span class="availability '+(d?'available':'')+'">'+(d?'For '+E(platformLabel(platform())):a.isBuiltin?'Included with ecosystem':'Other devices')+'</span><button class="mini-action '+(state.compare.includes(a.id)?'selected':'')+'" data-action="compare-add" data-id="'+E(a.id)+'" aria-label="'+(state.compare.includes(a.id)?'Remove':'Add')+' '+E(a.name)+' '+(state.compare.includes(a.id)?'from':'to')+' comparison">'+svg('Compare')+'</button><button class="mini-action '+(state.favorites.has(a.id)?'selected':'')+'" data-action="favorite" data-id="'+E(a.id)+'" aria-label="Save '+E(a.name)+'" aria-pressed="'+state.favorites.has(a.id)+'">'+svg('Library')+'</button></div></article>'}
function developerCard(d){const apps=allApps().filter(a=>a.developerId===d.id);return'<button class="developer-card" data-developer="'+E(d.id)+'">'+developerIcon(d)+'<div><h3>'+E(d.displayName)+' '+verified(d)+'</h3><p>'+apps.length+' '+(apps.length===1?'application':'applications')+' · '+(state.follows.has(d.id)?'Following':'View developer')+'</p></div><span class="arrow">→</span></button>'}
function chips(values,key,current){return'<div class="chips">'+values.map(v=>'<button class="action '+(current===v?'selected':'')+'" data-action="filter" data-key="'+key+'" data-value="'+E(v)+'" aria-pressed="'+(current===v)+'">'+E(v)+'</button>').join('')+'</div>'}
function sortedApps(apps){return[...apps].sort((a,b)=>{if(state.sort==='Top rated')return reviewInfo(b).average-reviewInfo(a).average||a.name.localeCompare(b.name);if(state.sort==='Newest')return(Number(b.timestamp)||0)-(Number(a.timestamp)||0)||a.name.localeCompare(b.name);if(state.sort==='A–Z')return a.name.localeCompare(b.name);if(state.sort==='Z–A')return b.name.localeCompare(a.name);if(state.sort==='Saved first')return Number(state.favorites.has(b.id))-Number(state.favorites.has(a.id))||a.name.localeCompare(b.name);return 0})}
function matchingApps(query=''){return sortedApps(allApps().filter(a=>{if(state.category!=='All'&&a.category!==state.category)return false;if(state.scope==='This device'&&!primaryDownload(a))return false;if(state.scope==='Other devices'&&primaryDownload(a))return false;if(state.scope==='Saved'&&!state.favorites.has(a.id))return false;if(state.publisher==='Woods Studio'&&!['woods-studio','woods-studio-labs'].includes(a.developerId))return false;if(state.publisher==='Third-party'&&['woods-studio','woods-studio-labs'].includes(a.developerId))return false;return[a.name,a.id,packageId(a),a.developer,developerFor(a)?.displayName,a.category,a.description].join(' ').toLowerCase().includes(query.toLowerCase().trim())}))}
function filters(){return'<div class="filter-panel">'+chips(['All',...categories()],'category',state.category)+chips(['All devices','This device','Other devices','Saved'],'scope',state.scope)+'<div class="filter-bottom"><label>Publisher <select data-state="publisher">'+['All publishers','Woods Studio','Third-party'].map(v=>'<option '+(state.publisher===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label>Sort <select data-state="sort">'+['Featured','A–Z','Z–A','Top rated','Newest','Saved first'].map(v=>'<option '+(state.sort===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><button class="text-button" data-action="reset-filters">Reset filters</button></div></div>'}
function discover(){const apps=allApps(),featured=apps.find(a=>!a.isBuiltin&&primaryDownload(a))||apps[0];if(!featured)return heading('Discover','Your next favourite is waiting.')+message('Connecting to the ecosystem','The catalogue will appear here when available.');const followed=apps.filter(a=>state.follows.has(a.developerId));return'<div class="discover-intro"><div><div class="eyebrow">A WORLD OF POSSIBILITY</div><h1>Good things.<br><span>All in one place.</span></h1><p>Discover what’s next in your ecosystem.</p></div><div class="count-note"><i></i>'+apps.length+' apps · Live catalogue</div></div><div class="hero-grid"><section class="hero"><div class="eyebrow">IN THE SPOTLIGHT</div><div class="hero-main">'+icon(featured,'hero-icon')+'<div class="hero-copy"><h2>'+E(featured.name)+'</h2><p>'+E(featured.description)+'</p></div></div>'+button('Take a closer look  →','explore','data-id="'+E(featured.id)+'"')+'</section><section class="feature-side"><span class="feature-emblem">'+svg('Discover')+'</span><div><div class="eyebrow">MADE TO EXPLORE</div><h2>Your device.<br>More possibilities.</h2><p>Apps for '+E(platformLabel(platform()))+' and every corner of the Clover ecosystem.</p></div><button data-nav="Browse">Explore the catalogue →</button></section></div>'+announcementsMarkup()+section('Find your collection','A good place to start.')+'<div class="collection-grid">'+state.collections.map((c,i)=>'<button class="collection-tile tone-'+i%4+'" data-collection="'+E(c.id)+'"><span>'+String((c.appIds||[]).length).padStart(2,'0')+' APPS</span><h3>'+E(c.title)+'</h3><p>'+E(c.description)+'</p><b>Explore collection →</b></button>').join('')+'</div>'+(followed.length?section('From developers you follow','Your people. Their latest ideas.')+grid(followed):'')+section('Meet the makers','The people behind your apps.','<button class="text-button" data-nav="Developers">All developers →</button>')+'<div class="developer-grid">'+state.developers.slice(0,3).map(developerCard).join('')+'</div>'+section('All applications','Every app. Every platform.','<button class="text-button" data-nav="Browse">Browse all →</button>')+grid(apps)}
function browse(){const apps=matchingApps();return heading('Find your kind of app.','Every platform. Every publisher. A little easier to discover.')+filters()+'<div class="search-meta"><span>'+apps.length+' applications</span><span>Viewing for '+E(platformLabel(platform()))+'</span></div>'+(apps.length?grid(apps):message('No apps in this selection','Try another category, device or publisher.'))}
function developersPage(){return heading('Meet the makers.','Discover the studios and people building your next favourite app.')+'<div class="developer-grid">'+state.developers.map(developerCard).join('')+'</div>'}
function developerPage(d){const apps=allApps().filter(a=>a.developerId===d.id);return'<button class="detail-back" data-action="back-profile">← All developers</button><section class="developer-hero" '+(httpsURL(d.banner)?'style="background-image:linear-gradient(0deg,#101726cc,#10172622),url(&quot;'+E(httpsURL(d.banner))+'&quot;)"':'')+'><div class="developer-heading">'+developerIcon(d)+'<div><div class="eyebrow">DEVELOPER PROFILE</div><h1>'+E(d.displayName)+'</h1>'+verified(d)+'<p>'+apps.length+' published '+(apps.length===1?'application':'applications')+'</p></div></div><div class="actions">'+button(state.follows.has(d.id)?'Following ✓':'Follow developer','follow','data-id="'+E(d.id)+'"')+button('Share profile','share-developer','data-id="'+E(d.id)+'"','','')+'</div></section>'+(d.description?'<section class="detail-panel"><p class="description">'+E(d.description)+'</p></section>':'')+'<div class="actions profile-links">'+[['Website',d.website],['Support',d.supportUrl],['Privacy policy',d.privacyPolicy]].filter(x=>httpsURL(x[1])).map(([name,url])=>button(name+' →','internal-browser','data-url="'+E(url)+'"','secondary')).join('')+'</div>'+announcementsMarkup(d.id)+section('From '+d.displayName,'All published applications.')+grid(apps)+'<p class="small muted">Following is saved in this browser. Cross-device follows and push announcements require a connected account service.</p>'}
function collectionPage(c){const apps=(c.appIds||[]).map(appById).filter(Boolean);return'<button class="detail-back" data-nav="Discover">← Discover</button>'+heading(c.title,c.description||'A collection from Clover Store.')+grid(apps)}
function announcementsMarkup(devId){const rows=state.announcements.filter(a=>(!devId||a.developerId===devId)&&(!a.expiresAt||Date.parse(a.expiresAt)>Date.now()));return rows.length?'<div class="announcement-list">'+rows.map(a=>'<article class="announcement"><div class="eyebrow">'+E(developerById(a.developerId)?.displayName||'ANNOUNCEMENT')+'</div><h3>'+E(a.title)+'</h3><p>'+E(a.body)+'</p>'+(httpsURL(a.url)?button('Read more →','internal-browser','data-url="'+E(a.url)+'"','secondary'):'')+'</article>').join('')+'</div>':''}
function searchPage(){return heading('What are you looking for?','Apps, makers and collections. One search away.')+'<div class="search-box">'+svg('Search')+'<input id="search" class="search-input" type="search" placeholder="Search the ecosystem…" aria-label="Search the ecosystem" value="'+E(state.query)+'"></div>'+chips(['All','Apps','Developers','Collections'],'searchKind',state.searchKind)+'<div id="results">'+searchResults()+'</div>'}
function searchResults(){const q=state.query.toLowerCase().trim(),apps=allApps().filter(a=>[a.name,a.developer,developerFor(a)?.displayName,a.id,packageId(a),a.description,a.category].join(' ').toLowerCase().includes(q)),devs=state.developers.filter(d=>[d.displayName,d.description,...(d.legacyNames||[])].join(' ').toLowerCase().includes(q)),collections=state.collections.filter(c=>[c.title,c.description].join(' ').toLowerCase().includes(q));return(!q?'<div class="recent-searches"><span class="eyebrow">RECENT SEARCHES</span><div class="chips">'+state.searches.map(v=>button(v,'search-term','data-value="'+E(v)+'"','secondary')).join('')+'</div></div>':'')+(['All','Developers'].includes(state.searchKind)?section('Developers',devs.length+' results')+'<div class="developer-grid">'+devs.map(developerCard).join('')+'</div>':'')+(['All','Collections'].includes(state.searchKind)&&collections.length?section('Collections',collections.length+' results')+'<div class="chips">'+collections.map(c=>'<button class="action secondary" data-collection="'+E(c.id)+'">'+E(c.title)+'</button>').join('')+'</div>':'')+(['All','Apps'].includes(state.searchKind)?section('Applications',apps.length+' results')+(apps.length?grid(apps):message('No apps found','Try a name, developer, package ID or category.')):'')}
function library(){const saved=allApps().filter(a=>state.favorites.has(a.id)),recent=state.recent.map(appById).filter(Boolean),follows=state.developers.filter(d=>state.follows.has(d.id));return heading('Your corner of Clover.','Keep what you love close. Saved in this browser.')+'<div class="library-toolbar">'+button('Export library','export-library','','secondary')+button('Import library','import-library','','secondary')+button('Clear recently viewed','clear-recent','','secondary')+'</div>'+section('Saved applications',saved.length+' apps')+(saved.length?grid(saved):message('Good things are worth saving.','Save an application to make it easy to find again.'))+(follows.length?section('Following','The makers you want to keep up with.')+'<div class="developer-grid">'+follows.map(developerCard).join('')+'</div>':'')+(recent.length?section('Recently viewed','Only stored on this device.')+grid(recent):'')+section('Get on another device','A local list of links to take with you.')+(state.handoff.length?'<div class="handoff-list">'+state.handoff.map((d,i)=>'<section class="message"><h3>'+E(d.name)+'</h3><p>'+E(platformLabel(d.platform))+' · '+E(new URL(d.url).hostname)+'</p><div class="actions">'+button('Copy link','copy','data-value="'+E(d.url)+'"','secondary')+button('Remove','handoff-remove','data-index="'+i+'"','secondary')+'</div></section>').join('')+'</div>':message('Bring it along','Use Save link under Other Downloads to keep a link here. Pairing and automatic delivery are not connected.'))}
function appWebsites(a){return[['Website',a.website||a.homepage],['Support',a.supportUrl],['Privacy policy',a.privacyPolicy]].filter(([,url])=>httpsURL(url)).map(([label,url])=>({label,url:httpsURL(url)}))}
function facts(rows){return'<dl class="facts">'+rows.map(([key,value])=>'<div><dt>'+E(key)+'</dt><dd>'+E(value??'Not provided')+'</dd></div>').join('')+'</dl>'}
function screenshotURLs(a){return(Array.isArray(a.screenshots)?a.screenshots:[]).map(s=>httpsURL(typeof s==='string'?s:s?.url)).filter(Boolean)}
function compatibility(a){const download=primaryDownload(a),sdk=download?.minSdk||a.minimumAndroidSdk,arches=download?.architectures;return(download?'A download for '+platformLabel(platform())+' is published. This does not independently verify device compatibility.':a.isBuiltin?'This application may be included with its target ecosystem. No standalone download is published for this device.':'No '+platformLabel(platform())+' download is published. See Other Downloads for other devices.')+(sdk?' Minimum Android SDK: '+sdk+'.':'')+(arches?.length?' Architectures: '+arches.join(', ')+'.':'')}
function details(a){const dev=developerFor(a),r=reviewInfo(a),main=primaryDownload(a),os=platformLabel(platform()),others=availableDownloads(a).filter(d=>d.key!==main?.key),shots=screenshotURLs(a),channels=[...new Set(['stable',...state.releases.filter(r=>r.appId===a.id).map(r=>r.channel)])];let reviews=[...r.list];if(state.reviewSort==='highest')reviews.sort((a,b)=>b.rating-a.rating);if(state.reviewSort==='lowest')reviews.sort((a,b)=>a.rating-b.rating);if(state.reviewSort==='newest')reviews.sort((a,b)=>(b.timestamp||Date.parse(b.date)||0)-(a.timestamp||Date.parse(a.date)||0));
return'<button class="detail-back" data-action="back">← Back</button><section class="detail-hero">'+icon(a,'detail-icon')+'<div class="detail-heading"><div class="eyebrow">'+E(a.category||'APPLICATION')+'</div><h1>'+E(a.name)+'</h1>'+(dev?'<button class="publisher-link" data-developer="'+E(dev.id)+'">'+E(dev.displayName)+' →</button>':'<p class="publisher">'+E(a.developer)+'</p>')+'<div class="detail-tags"><span class="tag">v'+E(main?.version||a.version||'—')+'</span>'+(r.average?'<span class="tag">★ '+r.average.toFixed(1)+' · '+r.valid.length+' ratings</span>':'<span class="tag">Not rated yet</span>')+'<span class="tag">'+(supplier(a)?'Supplier catalogue':'Third-party listing')+'</span></div></div><div class="detail-actions">'+(main?button('Download for '+os,'download','data-id="'+E(a.id)+'" data-platform="'+E(main.key)+'"'):'<div class="no-download">'+(a.isBuiltin?'Included with the ecosystem':'Not available for '+E(os))+'</div>')+'<div class="actions">'+button(state.favorites.has(a.id)?'Saved ✓':'Save','favorite','data-id="'+E(a.id)+'"','secondary')+button('Share','share','data-id="'+E(a.id)+'"','secondary')+button('QR','qr','data-id="'+E(a.id)+'"','secondary')+'</div></div></section><div class="detail-layout"><div class="detail-content">'+(shots.length?'<section class="detail-panel"><h2>A closer look</h2><div class="screenshot-gallery">'+shots.map((u,i)=>'<button data-action="screenshot" data-id="'+E(a.id)+'" data-index="'+i+'"><img loading="lazy" src="'+E(u)+'" alt="'+E(a.name)+' screenshot '+(i+1)+'"></button>').join('')+'</div></section>':'')+'<section class="detail-panel"><h2>About this application</h2><p class="description expandable" id="app-description">'+E(a.description||'The publisher has not provided a description.')+'</p>'+(String(a.description||'').length>450?button('Read more','expand-description','','secondary'):'')+'<div class="actions">'+appWebsites(a).map(l=>button(l.label+' →','internal-browser','data-url="'+E(l.url)+'"','secondary')).join('')+'</div></section><section class="detail-panel"><h2>What’s new</h2><p class="description">'+E(main?.changelog||a.changelog||'The publisher has not supplied release notes for this listing.')+'</p><div class="actions">'+button(state.watch[a.id]?'Tracking releases ✓':'Track releases','watch','data-id="'+E(a.id)+'"','secondary')+button('Compare app','compare-add','data-id="'+E(a.id)+'"','secondary')+'</div></section>'+(dev?'<section class="detail-panel"><h2>Meet the developer</h2>'+developerCard(dev)+'</section>':'')+'<section class="detail-panel"><div class="section-top"><div><h2>Ratings & reviews</h2><p>From the shared community catalogue.</p></div>'+button('Write a review','review','data-id="'+E(a.id)+'"','secondary')+'</div>'+(r.valid.length?'<div class="rating-summary"><div><div class="rating-number">'+r.average.toFixed(1)+'</div><p class="stars">'+stars(r.average)+'</p><p>'+r.valid.length+' ratings</p></div><div class="rating-bars">'+[5,4,3,2,1].map(n=>'<div class="rating-bar"><span>'+n+'</span><i><b style="width:'+r.valid.filter(r=>Number(r.rating)===n).length/r.valid.length*100+'%"></b></i></div>').join('')+'</div></div><div class="sort-row"><span>Community reviews</span><select id="review-sort" aria-label="Sort reviews">'+[['registry','Catalogue order'],['newest','Newest first'],['highest','Highest rated'],['lowest','Lowest rated']].map(([v,l])=>'<option value="'+v+'" '+(state.reviewSort===v?'selected':'')+'>'+l+'</option>').join('')+'</select></div>':'<p class="muted">No ratings yet.</p>')+reviews.map(x=>'<article class="review"><div class="review-top"><div class="avatar">'+E(initials(x.name||'Anonymous'))+'</div><div><h3>'+E(x.name||'Anonymous')+'</h3><p class="score">'+stars(x.rating)+' · '+E(x.rating)+'/5</p></div></div><p class="comment">'+E(x.comment)+'</p></article>').join('')+'<p class="review-note">Reviews reflect individual experiences. Names and ratings are not independently verified.</p></section></div><aside class="detail-aside"><section class="detail-panel"><h2>App information</h2>'+facts([['Developer',dev?.displayName||a.developer],['Version',main?.version||a.version],['Size',formatBytes(main?.sizeBytes||a.sizeBytes)],['Category',a.category],['Android package',validPackage(packageId(a))?packageId(a):supplier(a)?'Supplier-provided package':'Not provided'],['Version code',main?.versionCode||a.androidVersionCode||'Not provided']])+(channels.length>1?'<label class="field-label">Release channel<select data-channel="'+E(a.id)+'">'+channels.map(c=>'<option '+((state.channels[a.id]||'stable')===c?'selected':'')+'>'+E(c)+'</option>').join('')+'</select></label>':'')+'</section><section class="detail-panel"><h2>Will it work for me?</h2><p class="small muted">'+E(compatibility(a))+'</p><p class="package">Listing: '+E(a.id)+'</p></section><section class="detail-panel"><h2>Download source</h2><p class="small muted">'+E(main?new URL(main.url).hostname:'No download selected.')+'</p><p class="small muted source-note">'+(supplier(a)?'Woods Studio catalogue package-ID matching is exempt for supplier APKs. Android signature and update checks still apply in the native app.':'Third-party Android catalogue downloads require a matching package ID. A listing is not proof of safety or authenticity.')+'</p>'+(main?.sha256?'<p class="hash-label">PUBLISHED SHA-256</p><code class="hash">'+E(main.sha256)+'</code>':'')+'<div class="actions">'+button('Report a problem','report','data-id="'+E(a.id)+'"','secondary')+'</div></section><section class="detail-panel"><h2>Other Downloads</h2><p class="small muted">For your other devices.</p>'+(others.length?others.map(d=>'<div class="platform-row"><div class="platform-info"><strong>'+E(platformLabel(d.key))+'</strong><small>v'+E(d.version||a.version||'—')+'</small></div><div class="platform-actions">'+button('Download','download','data-id="'+E(a.id)+'" data-platform="'+E(d.key)+'"','secondary')+button('Save link','handoff','data-id="'+E(a.id)+'" data-platform="'+E(d.key)+'"','secondary')+'</div></div>').join(''):'<p class="small muted source-note">No other downloads have been published.</p>')+'</section></aside></div>'}
function watchApp(a,code){const current=primaryDownload(a);state.watch[a.id]={versionCode:Number(code||current?.versionCode||a.androidVersionCode||a.versionCode)||null,version:current?.version||a.version||'',platform:platform(),channel:state.channels[a.id]||'stable',watchedAt:Date.now()};saveLocal('watch',state.watch);toast('Tracking this catalogue version. This does not detect an installed app.');render()}
function updateRows(){return Object.entries(state.watch).map(([id,previous])=>{const a=appById(id);if(!a)return'';const latest=availableDownloads(a,previous.channel||'stable').find(d=>d.key===(previous.platform||platform())),code=Number(latest?.versionCode||a.androidVersionCode||a.versionCode)||null;const changed=previous.versionCode&&code?code>previous.versionCode:String(latest?.version||a.version)!==String(previous.version);return'<section class="message update-row"><div>'+icon(a)+'<div><h3>'+E(a.name)+'</h3><p>'+E(previous.version)+' → '+E(latest?.version||a.version)+' · '+E(platformLabel(previous.platform||platform()))+' / '+E(previous.channel||'stable')+'</p><span class="tag">'+(changed?'New catalogue version':'Tracking current listing')+'</span></div></div><div class="actions"><button class="action secondary" data-open="'+E(id)+'">View app</button>'+button('Mark seen','watch','data-id="'+E(id)+'"','secondary')+button('Stop tracking','unwatch','data-id="'+E(id)+'"','secondary')+'</div></section>'}).join('')}
function updatesPage(){return heading('Keep good things current.','Follow release changes without losing your place.')+message('Release tracking in HTML','A webpage cannot reliably inspect installed applications. This centre compares the catalogue with versions you explicitly track. Native installation detection and automatic app updates require the Android app.')+(Object.keys(state.watch).length?'<div class="updates-list">'+updateRows()+'</div>':message('Start following releases','Open an app and choose Track releases. Only real published metadata is used.'))}
function comparisonPage(){const apps=state.compare.map(appById).filter(Boolean);return heading('A clearer choice.','Compare up to three applications, side by side.')+(apps.length?'<div class="compare-scroll"><table class="comparison"><thead><tr><th>Compare</th>'+apps.map(a=>'<th>'+icon(a)+'<h3>'+E(a.name)+'</h3>'+button('Remove','compare-add','data-id="'+E(a.id)+'"','secondary')+'</th>').join('')+'</tr></thead><tbody>'+[['Developer',a=>developerFor(a)?.displayName||a.developer],['Version',a=>a.version],['Platforms',a=>availableDownloads(a).map(d=>platformLabel(d.key)).join(', ')||'No public downloads'],['Rating',a=>reviewInfo(a).average?reviewInfo(a).average.toFixed(1)+' / 5':'Not rated'],['Package ID',a=>packageId(a)],['Size',a=>formatBytes(primaryDownload(a)?.sizeBytes||a.sizeBytes)],['Android minimum SDK',a=>a.minimumAndroidSdk||primaryDownload(a)?.minSdk||'Not provided'],['Description',a=>a.description]].map(([name,fn])=>'<tr><th>'+E(name)+'</th>'+apps.map(a=>'<td>'+E(fn(a))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':message('Put a few favourites side by side','Use the comparison button on app cards or app pages.'))}
function selectPref(key,label,values){return'<label class="setting-field"><span>'+E(label)+'</span><select data-pref="'+key+'">'+values.map(v=>{const value=Array.isArray(v)?v[0]:v,name=Array.isArray(v)?v[1]:v;return'<option value="'+E(value)+'" '+(String(prefs[key])===String(value)?'selected':'')+'>'+E(name)+'</option>'}).join('')+'</select></label>'}
function togglePref(key,label,desc){return'<label class="toggle-field"><span><strong>'+E(label)+'</strong><small>'+E(desc)+'</small></span><input type="checkbox" data-pref="'+key+'" '+(prefs[key]?'checked':'')+'></label>'}
const THEMES=[
 {id:'pure-black',name:'Pure Black',group:'Essentials',mode:'dark',background:'#000',description:'The original Clover Store background.'},
 {id:'aurora',name:'Aurora',group:'Gradients',mode:'dark',background:'radial-gradient(ellipse at 15% 10%,#175b5880,transparent 60%),radial-gradient(ellipse at 85% 45%,#533c8a90,transparent 65%),linear-gradient(150deg,#050c18,#0d1824)',description:'Teal and violet light across a midnight sky.'},
 {id:'violet-haze',name:'Violet Haze',group:'Gradients',mode:'dark',background:'radial-gradient(ellipse at 80% 5%,#713c9b90,transparent 65%),radial-gradient(ellipse at 0% 100%,#293b8c90,transparent 65%),linear-gradient(140deg,#100a1e,#16162e)',description:'Soft purple clouds and deep indigo.'},
 {id:'ocean',name:'Deep Ocean',group:'Gradients',mode:'dark',background:'radial-gradient(ellipse at 90% 15%,#12648690,transparent 65%),radial-gradient(ellipse at 5% 80%,#13463d80,transparent 65%),linear-gradient(165deg,#06121b,#0b1b36)',description:'Cool blue depths with a hint of sea green.'},
 {id:'ember',name:'Ember',group:'Gradients',mode:'dark',background:'radial-gradient(ellipse at 20% 0%,#964d3480,transparent 60%),radial-gradient(ellipse at 90% 90%,#70224780,transparent 65%),linear-gradient(145deg,#1c0b10,#190f22)',description:'Copper, burgundy and the last light of sunset.'},
 {id:'rose-dawn',name:'Rose Dawn',group:'Gradients',mode:'light',background:'radial-gradient(ellipse at 0% 0%,#f5cfdd,transparent 65%),radial-gradient(ellipse at 100% 75%,#d0d9f8,transparent 65%),linear-gradient(140deg,#fcf5f0,#eae7fb)',description:'An airy rose and lavender palette.'},
 {id:'obsidian-dark',name:'Splash Obsidian · Dark',group:'Splash Obsidian',mode:'dark',background:'radial-gradient(ellipse 90% 38% at 90% 115%,#6d6cba90 0%,#34394e80 40%,transparent 75%),radial-gradient(ellipse 100% 48% at -15% -5%,#5d687780 0%,#20293670 40%,transparent 75%),linear-gradient(145deg,#06080e,#161923 55%,#080b13)',description:'Obsidian-inspired silver folds over charcoal.'},
 {id:'obsidian-light',name:'Splash Obsidian · Light',group:'Splash Obsidian',mode:'light',background:'radial-gradient(ellipse 95% 40% at 105% 115%,#b9b5de 0%,#d1d4e2 42%,transparent 76%),radial-gradient(ellipse 105% 50% at -20% -5%,#b4c3d3 0%,#d9e1e9 44%,transparent 76%),linear-gradient(145deg,#f8fafc,#e8ebf3 55%,#f6f5fc)',description:'Obsidian-inspired pearl folds and soft lilac.'}
];
function selectedTheme(){return THEMES.find(t=>t.id===prefs.wallpaper)||THEMES[0]}
function themesPanel(){const selected=selectedTheme();return '<section class="detail-panel themes-panel" aria-labelledby="themes-title"><div class="section-top"><div><div class="eyebrow">YOUR STORE, YOUR ATMOSPHERE</div><h2 id="themes-title">Themes</h2><p>Choose a background. Cards and text adapt to its light or dark palette.</p></div><span class="theme-current">'+E(selected.name)+'</span></div>'+['Essentials','Gradients','Splash Obsidian'].map(group=>'<h3 class="theme-group">'+E(group)+'</h3><div class="theme-grid">'+THEMES.filter(t=>t.group===group).map(t=>'<button class="theme-option" data-action="select-theme" data-theme-id="'+E(t.id)+'" aria-pressed="'+(selected.id===t.id)+'" aria-label="Apply '+E(t.name)+' theme"><span class="theme-preview '+t.mode+'" style="background:'+E(t.background)+'"><span class="theme-mini-sidebar"></span><span class="theme-mini-cards"><i></i><i></i><i></i></span><span class="theme-selected" aria-hidden="true">'+(selected.id===t.id?'✓':'')+'</span></span><span class="theme-name">'+E(t.name)+'</span><span class="theme-description">'+E(t.description)+'</span></button>').join('')+'</div>').join('')+'<p class="small muted source-note">Splash Obsidian styles are original CSS wallpapers inspired by Obsidian. Your choice is saved on this browser. Startup and connection screens keep their black background.</p></section>'}
function notificationStatus(){
 if(!window.isSecureContext)return 'Notifications need a secure HTTPS website.';
 if(!('Notification'in window))return 'Notifications are not supported in this browser.';
 return {granted:'Notifications are allowed.',denied:'Notifications are blocked. Change this website’s notification permission in your browser’s site settings.',default:'Notifications have not been requested.'}[Notification.permission]||'Notification permission is unavailable.';
}
async function requestNotifications(){
 if(!window.isSecureContext||!('Notification'in window)){toast(notificationStatus());return}
 if(Notification.permission==='denied'){toast(notificationStatus());return}
 try{await Notification.requestPermission();if(state.tab==='Settings')render();toast(notificationStatus())}catch{toast('Notification permission could not be requested. Use your browser’s site settings.')}
}
function testNotification(){
 if(!('Notification'in window)||Notification.permission!=='granted'){toast('Allow notifications first using Request notifications.');return}
 try{new Notification('Clover Store',{body:'Notifications are ready. Download alerts will appear while the store is open.',icon:document.querySelector('.store-icon')?.src});toast('Test notification sent.')}catch{toast('This browser cannot show desktop notifications here.')}
}
async function chooseDownloadFolder(){
 if(!window.isSecureContext||!window.showDirectoryPicker){toast('Folder selection is unavailable here. Save files with your browser’s download controls.');return}
 try{downloadFolder=await window.showDirectoryPicker({id:'clover-downloads',mode:'readwrite'});if(state.tab==='Settings')render();toast('Download folder selected for this session.')}catch(e){if(e.name!=='AbortError')toast('Folder access was not granted.')}
}
async function saveAllReady(){
 if(batchSaving)return;
 if(!prefs.multipleFiles){toast('Enable Save multiple files together in Settings first.');return}
 const ready=state.downloads.filter(d=>d.status==='Ready to save'&&fileBlobs.has(d.id));
 if(!ready.length){toast('No files are ready to save. Add downloads from an app page first.');return}
 batchSaving=true;let saved=0;
 try{
  for(const d of ready){
   if(!downloadFolder){saveDownload(d);saved++;continue}
   const original=String(d.filename||d.name||'download').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').replace(/[. ]+$/,'')||'download';
   const dot=original.lastIndexOf('.'),stem=dot>0?original.slice(0,dot):original,ext=dot>0?original.slice(dot):'';
   let name=original,index=0;
   for(;;){try{await downloadFolder.getFileHandle(name);name=stem+' ('+(++index)+')'+ext}catch(e){if(e.name==='NotFoundError')break;throw e}}
   const handle=await downloadFolder.getFileHandle(name,{create:true});const writer=await handle.createWritable();
   try{await writer.write(fileBlobs.get(d.id));await writer.close()}catch(e){try{await writer.abort()}catch{}throw e}
   const url=fileURLs.get(d.id);if(url)URL.revokeObjectURL(url);fileURLs.delete(d.id);fileBlobs.delete(d.id);d.status='Saved to folder';saved++;refreshDownloads();
  }
  toast(downloadFolder?saved+' files saved to your chosen folder.':saved+' files handed to your browser. Allow multiple downloads if prompted.');
 }catch{toast(saved+' files saved. Folder access or a write failed; the remaining files are still ready to save.')}finally{batchSaving=false;refreshDownloads()}
}
function settings(){return heading('Make yourself at home.','Clover Store '+VERSION+' · HTML5 edition')+'<div class="settings-grid">'+themesPanel()+'<section class="detail-panel"><h2>Make it yours</h2>'+'<p class="small muted">Accent and layout</p>'+selectPref('accent','Accent',[['violet','Violet'],['blue','Blue'],['mint','Mint'],['rose','Rose']])+selectPref('density','Card spacing',[['comfortable','Comfortable'],['compact','Compact']])+selectPref('textSize','Text size',[['100','Standard'],['110','Larger'],['125','Largest']])+selectPref('motion','Animation',[['auto','Follow device'],['reduce','Reduced motion']])+togglePref('haptics','Touch feedback','Uses vibration only on browsers that support it.')+'</section><section class="detail-panel"><h2>Downloads & connection</h2>'+selectPref('concurrency','Simultaneous downloads',['1','2','3'])+togglePref('wifiOnly','Wi-Fi only','Only starts transfers if the browser can confirm Wi-Fi. Otherwise it waits.')+togglePref('chargingOnly','Only when charging','Requires browser battery information; otherwise it waits.')+'<p class="small muted source-note">Queued and scheduled downloads run only while this page remains open. External browser downloads are outside Clover Store’s control.</p></section><section class="detail-panel"><h2>Your data, your controls</h2><div class="stack-actions">'+button('Disclaimers','disclaimers','','secondary')+button('Export library','export-library','','secondary')+button('Import library','import-library','','secondary')+button('Clear recently viewed & searches','clear-recent','','secondary')+button('Clear completed download history','clear-downloads','','secondary')+button('Clear Clover Store data','clear-data','','secondary')+'</div></section><section class="detail-panel"><h2>Connected to your ecosystem</h2><p class="small muted">GitHub catalogue refreshes every 30 seconds while visible. Developer profiles, collections and published reviews use the same repository.</p><div class="stack-actions">'+button('Refresh catalogue','sync','','secondary')+button('View repository →','internal-browser','data-url="'+REPO+'"','secondary')+button('Copy diagnostics','diagnostics','','secondary')+button('What’s new in 1.5','whatsnew','','secondary')+'</div></section><section class="detail-panel"><h2>Web browsing</h2>'+togglePref('externalWebsites','Open websites in a new tab','Use your browser instead of the built-in Clover Store browser. Applies to website links, developer websites and announcements.')+'<div class="stack-actions">'+button('Open a website','open-address','','secondary')+'</div></section><section class="detail-panel"><h2>Notifications</h2><p class="small muted" role="status">'+E(notificationStatus())+'</p><p class="small muted">Get download-ready alerts while Clover Store is open. Notifications from a closed store require a separate push service.</p><div class="stack-actions">'+button('Request notifications','notifications','','secondary')+button('Send test notification','test-notification','','secondary')+'</div></section><section class="detail-panel"><h2>Files & browser permissions</h2>'+togglePref('multipleFiles','Save multiple files together','Enables Save all ready files. Your browser may ask whether this site can download multiple files.')+'<p class="small muted">Automatic downloads are controlled by your browser. If blocked, open this website’s site settings and allow Automatic downloads, or save each file separately.</p><p class="small muted" id="download-folder-status">'+E(downloadFolder?'Selected folder: '+downloadFolder.name:'No download folder selected. Your browser chooses where individual files are saved.')+'</p><div class="stack-actions">'+button('Choose download folder','choose-download-folder','','secondary')+button('Forget selected folder','forget-download-folder','','secondary')+button('Save all ready files','save-all-ready','','secondary')+'</div><p class="small muted source-note">Folder selection is available in supported desktop browsers over HTTPS. Access is requested only when you choose a folder and lasts for this session. Existing files are never overwritten; duplicate names receive a number.</p></section></div>'}
function disclosures(){return heading('Disclaimers','Privacy, permissions and important information for the HTML edition.')+'<button class="detail-back" data-nav="Settings">← Back to Settings</button>'+[
['Privacy at a glance','This HTML app includes no advertising, analytics or crash-reporting SDK. It has no connected account service. Saved apps, follows, release tracking, recent views/searches, handoff links, preferences and download records stay in this browser unless you explicitly export or share them.'],
['Network information','GitHub receives catalogue requests. Image and download hosts receive requests when artwork or files are loaded. Those services can see IP addresses, requested URLs, times and browser request metadata, and may log them under their own policies. Refreshes occur every 30 seconds while the page is visible.'],
['Browser storage','Local storage keeps preferences and personal lists; IndexedDB caches the last valid catalogue when available. Downloaded blobs exist temporarily in memory until saved or the page closes. Browser storage may be cleared or unavailable in private modes. Exported files and files saved by the browser remain until you delete them separately.'],
['Permissions in HTML','This webpage does not declare Android permissions and cannot request REQUEST_INSTALL_PACKAGES. Android installation is controlled by your browser and operating system. File import and APK inspection read only files you choose, without uploading them. Notifications require an explicit request and browser consent. Clipboard, sharing, storage estimates, battery/network information and vibration depend on browser support and may be restricted. It does not request camera, microphone, contacts or location.'],
['Websites and embedded browsing','Sites opened in the internal frame have their own privacy practices, cookies and storage. JavaScript and form uploads may be available to those sites. The store cannot read cross-origin page addresses or navigation history, clear another site’s cookies, or override embedding restrictions. The toolbar identifies the opened website when the current URL is unavailable. Open in browser is always provided.'],
['Downloads and schedules','Progress is shown only when a host permits the browser to fetch the file. Files larger than the memory limit or blocked by cross-origin restrictions must use normal browser downloads. Schedules and queues do not run after the page is closed. Wi-Fi and charging rules wait when the browser cannot verify the required condition. Saved status is not proof of installation.'],
['Supplier and third-party apps','A publisher label, package ID, icon or profile is not independent proof of ownership, authenticity or safety. Woods Studio supplier listings are exempt from catalogue package-ID matching. Third-party Android listings require package identifiers. The native Android app still applies Android signature/update checks. This HTML page does not install APKs or bypass operating-system checks.'],
['APK inspection limits','Inspection reads ZIP entries and manifest metadata locally, computes SHA-256, and can extract certificate fingerprints from supported APK v2/v3 signing blocks. Extracting a certificate is not cryptographic APK-signature verification and is not a malware scan. Unsupported formats and v1-only signatures may not yield certificate details. Treat inspection as information, not certification.'],
['Reviews and submissions','Published reviews are public and not independently verified. The in-app review API is not connected. Preparing a review or developer/app submission creates an explicit GitHub issue draft or downloads JSON; it does not silently publish data. A maintainer must approve the issue. Do not include passwords, private device identifiers or sensitive information.'],
['Updates and compatibility','The webpage cannot reliably detect your installed apps or actual installed versions. Release tracking compares metadata with versions you choose to track. File size, supported platforms, version codes and requirements are shown only when published. Empty metadata is not a compatibility guarantee.'],
['Remove your data','Settings can clear Clover Store’s personal lists, cached catalogue and completed download records. This does not delete saved files, exported documents, third-party website cookies or remote host logs. To clear embedded-site data, use your browser’s site-data settings. Disabling notifications and other browser permissions is also managed by your browser.'],
['Current capabilities','Developer pages, collections, follows, comparison, library import/export, release tracking, local handoff lists, APK inspection and queued downloads run locally. Cross-device sync, real account management, durable background downloads, native installation, silent updates and the developer publishing website are not supplied by this HTML file.']
].map(([t,d])=>message(t,d)).join('')}
function whatsNew(){modal('A little more Clover.', '<div class="eyebrow">WHAT’S NEW / 1.5</div><h3>A whole ecosystem, closer.</h3><p>Meet developers, follow their work, explore collections, compare apps, track releases and make the store yours.</p><ul><li>Developer profiles and collection pages.</li><li>Smarter search, library tools and recent activity.</li><li>Queue and schedule downloads with real progress where supported.</li><li>Local APK metadata and certificate-fingerprint inspection.</li><li>Appearance, accessibility and detailed Disclaimers.</li></ul><p class="small muted">Connected services and native Android functions are clearly identified when unavailable.</p>'+button('Explore the catalogue','new-dismiss'),'wide')}
function inspectorPage(){return heading('Know what you’re opening.','Inspect an APK locally before handing it to Android.')+message('Files stay on your device','Choose a standalone APK up to 128 MB. Clover Store reads manifest metadata, hashes the file and extracts supported signer fingerprints locally. It does not upload the file, install it, verify APK signatures or scan for malware.')+'<section class="detail-panel"><label class="file-drop">'+svg('Inspector')+'<strong>Choose an Android APK</strong><span>Package, version, permissions and SHA-256</span><input id="apk-file" type="file" accept=".apk,application/vnd.android.package-archive"></label><div id="apk-results">'+(inspection?inspectionMarkup(inspection):'')+'</div></section>'}
function inspectionMarkup(info){return'<div class="inspection-result"><h2>'+E(info.packageName)+'</h2>'+facts([['File',inspectionFile?.name],['Version',info.versionName||'Not resolved'],['Version code',info.versionCode||'Not found'],['Minimum SDK',info.minSdk||'Not declared'],['Target SDK',info.targetSdk||'Not declared'],['File size',formatBytes(info.size)]])+'<h3>Actual file SHA-256</h3><code class="hash">'+E(info.sha256)+'</code><h3>Extracted signing certificates</h3>'+(info.certificates.length?info.certificates.map(c=>'<p class="small muted">'+E(c.scheme)+' certificate · not cryptographically verified</p><code class="hash">'+E(c.sha256.match(/.{2}/g).join(':').toUpperCase())+'</code>').join(''):'<p class="small muted">No supported v2/v3 signer information was extracted. This does not establish that the APK is unsigned; v1-only signatures are not inspected.</p>')+'<h3>Declared permissions</h3>'+(info.permissions.length?'<ul class="permission-list">'+info.permissions.map(p=>'<li>'+E(p)+'</li>').join('')+'</ul>':'<p class="small muted">No uses-permission entries found.</p>')+'<h3>Catalogue matches</h3>'+allApps().filter(a=>packageId(a)===info.packageName).map(a=>'<button class="action secondary" data-open="'+E(a.id)+'">'+E(a.name)+'</button>').join('')+'<p class="small muted source-note">HTML cannot invoke Android’s PackageInstaller. Use the original file in your operating system to install it. The native Android edition supplies installation controls.</p></div>'}
function queueStateReason(d){if(!navigator.onLine)return'Waiting for an internet connection';if(d.notBefore&&Date.now()<d.notBefore)return'Scheduled for '+new Date(d.notBefore).toLocaleString();if(prefs.wifiOnly){const type=navigator.connection?.type;if(!type)return'Waiting: browser cannot confirm Wi-Fi';if(type!=='wifi')return'Waiting for Wi-Fi'}if(prefs.chargingOnly){if(!battery)return'Waiting: charging information unavailable';if(!battery.charging)return'Waiting for charging'}return''}
function downloadRows(){return state.downloads.length?state.downloads.map(d=>{const active=['Downloading','Checking'].includes(d.status),waiting=d.status==='Queued',reason=waiting?queueStateReason(d):d.reason||'',rate=speedSamples.get(d.id)||0;return'<section class="download queue-item"><div class="queue-heading"><div><h3>'+E(d.name)+'</h3><p>'+E(platformLabel(d.platform))+' · '+E(d.status)+'</p></div><span class="queue-host">'+E(new URL(d.url).hostname)+'</span></div>'+(active?'<progress '+(d.total?'value="'+d.done+'" max="'+d.total+'"':'')+' aria-label="Download progress"></progress>':'')+'<p class="small muted">'+(d.done?formatBytes(d.done)+(d.total?' / '+formatBytes(d.total):''):'')+(active&&rate?' · '+formatBytes(rate)+'/s'+(d.total?' · about '+Math.ceil((d.total-d.done)/rate)+' seconds remaining':''):'')+'</p>'+(reason?'<p class="small muted source-note">'+E(reason)+'</p>':'')+'<div class="actions">'+(active||waiting?button('Cancel','cancel','data-id="'+E(d.id)+'"','secondary')+(waiting?button('Move up','queue-up','data-id="'+E(d.id)+'"','secondary')+button('Download now','queue-now','data-id="'+E(d.id)+'"','secondary'):''):d.status==='Ready to save'&&fileURLs.has(d.id)?button('Save file','save-download','data-id="'+E(d.id)+'"'):button('Retry in store','retry-download','data-id="'+E(d.id)+'"','secondary'))+button('Open browser link','direct-download','data-id="'+E(d.id)+'"','secondary')+'</div></section>'}).join(''):message('Nothing downloading','Start a download from an app page. Your browser manages files after you save them.')}
function downloadsPage(){return heading('Your next download.','A little more control, without the clutter.')+'<div class="library-toolbar">'+button('Save all ready files','save-all-ready','','secondary')+button('Clear completed history','clear-downloads','','secondary')+'<button class="action secondary" data-nav="Inspector">Inspect a local APK</button><button class="action secondary" data-nav="Settings">Download preferences</button></div><div id="download-list">'+downloadRows()+'</div><p class="small muted downloads-note">Progress requires permission from the file host. Memory downloads are limited to 128 MB. Use Open browser link when a host blocks cross-origin transfers. Schedules work only while this page remains open.</p>'}
function persistDownloads(){saveLocal('downloads',state.downloads.map(({id,appId,name,url,platform,filename,status,done,total,stamp,notBefore,reason,expectedHash})=>({id,appId,name,url,platform,filename,status,done,total,stamp,notBefore,reason,expectedHash})))}
function refreshDownloads(){persistDownloads();if(state.tab==='Downloads'&&!state.detail&&$('#download-list'))$('#download-list').innerHTML=downloadRows()}
async function enqueue(a,key,notBefore=0){const item=availableDownloads(a).find(d=>d.key===(key||platform()));if(!item){toast('No download is published for this device/channel.');return}if(item.key==='android'&&!supplier(a)&&!validPackage(packageId(a))){toast('This third-party listing needs an Android package ID.');return}if(item.sizeBytes&&navigator.storage?.estimate){try{const{quota,usage}=await navigator.storage.estimate();if(quota&&item.sizeBytes>quota-usage){modal('Storage may be limited','<p>The browser reports less available storage than this file needs. Use your browser’s download manager or free some space.</p>'+button('Open download link','open-link','data-url="'+E(item.url)+'"'));return}}catch{}}
const ext=new URL(item.url).pathname.match(/\.([a-z0-9]{1,8})$/i)?.[0]||'',d={id:crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),appId:a.id,name:a.name,url:item.url,platform:item.key,filename:String(a.name).replace(/[^a-zA-Z0-9._ -]/g,'_')+ext,status:'Queued',done:0,total:item.sizeBytes||0,stamp:Date.now(),notBefore,expectedHash:item.sha256||null};state.downloads.push(d);persistDownloads();closeModal();navigate('Downloads');pumpDownloads()}
function downloadOptions(a,key){const item=availableDownloads(a).find(d=>d.key===key);if(!item)return;modal('Make room for something good.','<h3>'+E(a.name)+'</h3><p>'+E(platformLabel(key))+' · '+E(new URL(item.url).hostname)+'</p><p class="small muted">'+E(compatibility(a))+'</p><div class="actions">'+button('Download now','enqueue','data-id="'+E(a.id)+'" data-platform="'+E(key)+'"')+button('Schedule','schedule','data-id="'+E(a.id)+'" data-platform="'+E(key)+'"','secondary')+button('Open browser link','open-link','data-url="'+E(item.url)+'"','secondary')+'</div>')}
function pumpDownloads(){if(document.hidden)return;let slots=Math.max(1,Math.min(3,Number(prefs.concurrency)||1))-controllers.size;for(const d of state.downloads){if(slots<=0)break;if(d.status==='Queued'&&!queueStateReason(d)){slots--;transfer(d)}}}
async function transfer(d){d.status='Downloading';d.reason='';d.done=0;const c=new AbortController();controllers.set(d.id,c);refreshDownloads();let sample=Date.now(),sampleBytes=0,lastDraw=0;try{const response=await fetch(d.url,{signal:c.signal});if(!response.ok||!response.body)throw Error('The host did not return a readable file.');const mime=response.headers.get('Content-Type')||'';if(mime.includes('text/html'))throw Error('The host returned a web page instead of a file.');d.total=Number(response.headers.get('Content-Length'))||d.total||0;if(d.total>134217728)throw Error('This file exceeds the 128 MB memory limit. Use the browser download link.');const reader=response.body.getReader(),chunks=[];while(true){const{done,value}=await reader.read();if(done)break;chunks.push(value);d.done+=value.length;if(d.done>134217728){await reader.cancel();throw Error('This file exceeds the 128 MB memory limit. Use the browser download link.')}const now=Date.now();if(now-sample>600){speedSamples.set(d.id,(d.done-sampleBytes)/((now-sample)/1000));sample=now;sampleBytes=d.done}if(now-lastDraw>300){refreshDownloads();lastDraw=now}}
const blob=new Blob(chunks,{type:mime||'application/octet-stream'});if(d.expectedHash){d.status='Checking';refreshDownloads();if(!crypto.subtle)throw Error('Published checksum cannot be checked in this browser context.');const hash=await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()),actual=[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('');if(actual!==String(d.expectedHash).toLowerCase())throw Error('The file does not match its published SHA-256. Do not install it.')}if(c.signal.aborted)throw Error('Cancelled');if([...fileBlobs.values()].reduce((n,b)=>n+b.size,0)+blob.size>268435456)throw Error('The browser memory limit for ready files was reached. Save/clear completed files or use the browser download link.');fileBlobs.set(d.id,blob);fileURLs.set(d.id,URL.createObjectURL(blob));d.status='Ready to save';notify(d.name+' is ready to save.');}catch(error){d.status=c.signal.aborted?'Cancelled':'Use browser download';d.reason=c.signal.aborted?'Cancelled in Clover Store.':error instanceof TypeError?'The file host did not allow this in-app transfer, or the connection failed. Use Open browser link.':error.message||'The browser could not read this transfer.';}finally{controllers.delete(d.id);speedSamples.delete(d.id);refreshDownloads();pumpDownloads()}}
function saveDownload(d){const link=fileURLs.get(d.id);if(!link){toast('This file is no longer in memory. Download it again.');return}downloadLink(link,d.filename||d.name);d.status='Handed to browser';fileBlobs.delete(d.id);fileURLs.delete(d.id);setTimeout(()=>URL.revokeObjectURL(link),10000);refreshDownloads()}
function downloadLink(url,filename){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';if(filename)a.download=filename;document.body.append(a);a.click();a.remove()}
function directDownload(d){downloadLink(d.url,d.filename);d.status='Handed to browser';refreshDownloads()}
function compareAdd(id){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else{toast('Compare up to three apps at a time.');return}render();toast(state.compare.length+' apps in comparison')}
function shareURL(kind,id){const route=kind+'='+encodeURIComponent(id),configured=httpsURL(prefs.publicUrl);if(configured)return configured.split('#')[0]+'#'+route;if(location.protocol==='https:'||location.protocol==='http:')return location.href.split('#')[0]+'#'+route;return REPO+'/blob/main/'+(kind==='app'?'apps/'+encodeURIComponent(id)+'.json':'developers.json')}
async function share(text){try{if(navigator.share){await navigator.share({text});return}if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);toast('Copied to clipboard');return}}catch(e){if(e.name==='AbortError')return}modal('Copy to share','<textarea readonly class="copy-area">'+E(text)+'</textarea>')}
function qrDialog(kind,id){const url=shareURL(kind,id);try{const code=qrcode(0,'M');code.addData(url);code.make();modal('A little easier to share.','<div class="qr-code">'+code.createSvgTag({cellSize:5,margin:4,scalable:true})+'</div><p class="small muted">'+E(url)+'</p>'+button('Copy link','copy','data-value="'+E(url)+'"','secondary'))}catch{toast('This link is too long to encode as a QR code.')}}
function modal(title,content,extra=''){const d=$('#feature-dialog');$('#feature-title').textContent=title;$('#feature-content').innerHTML=content;d.className='native-sheet feature-dialog '+extra;if(!d.open)d.showModal();d.querySelector('button,input,select,textarea')?.focus()}
function closeModal(){if($('#feature-dialog').open)$('#feature-dialog').close()}
function exportJSON(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));downloadLink(url,name);setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportLibrary(){exportJSON('CloverStore-library.json',{format:'clover-library',version:1,savedAppIds:[...state.favorites],followedDeveloperIds:[...state.follows]})}
async function importLibrary(file){try{if(file.size>262144)throw Error('Choose an export smaller than 256 KB.');const data=JSON.parse(await file.text());if(!['clover-library','clover-saved-apps'].includes(data.format)||data.version!==1)throw Error('Choose a supported Clover Store library export.');const saved=data.savedAppIds,followed=data.followedDeveloperIds||[];if(!Array.isArray(saved)||!Array.isArray(followed)||saved.length+followed.length>1000||[...saved,...followed].some(x=>typeof x!=='string'||!x.trim()||x.length>256))throw Error('The export contains invalid IDs.');for(const id of saved)state.favorites.add(id);for(const id of followed)state.follows.add(id);saveLocal('favorites',[...state.favorites]);saveLocal('follows',[...state.follows]);toast('Library merged. Unpublished apps appear when available.');render()}catch(e){toast(e.message||'Unable to import this file.')}}
function submissionDraft(kind,id){let data;if(kind==='review'){data={appId:id,name:'',rating:5,comment:''};modal('Share your experience.','<p>Reviews are published through the moderated GitHub workflow. Nothing is posted automatically.</p><label class="setting-field">Public display name<input id="draft-name" maxlength="100"></label><label class="setting-field">Rating<select id="draft-rating">'+[5,4,3,2,1].map(n=>'<option>'+n+'</option>').join('')+'</select></label><label class="setting-field">Your review<textarea id="draft-comment" maxlength="8000" rows="5"></textarea></label><p class="small muted">This creates a public GitHub issue draft. Maintainer approval is required. No review API is connected.</p>'+button('Prepare GitHub draft','review-draft','data-id="'+E(id)+'"'));return}
data=kind==='developer'?{id:'your-studio',displayName:'Your Studio',description:'Your public description',icon:null,banner:null,website:null}:{id:'your-app-listing',developerId:'your-studio',name:'Your App',category:'App Suite',version:'1.0',description:'Your app description',icon:'https://example.com/app-icon.png',androidPackageName:'com.example.android.app',downloads:{android:'https://example.com/app.apk'}};modal(kind==='developer'?'Prepare your developer profile.':'Prepare your app listing.','<p>The dedicated publishing website is not deployed. You can prepare a JSON submission for the moderated GitHub workflow instead. Replace example values with real information.</p><textarea id="draft-json" class="copy-area" rows="12">'+E(JSON.stringify(data,null,2))+'</textarea><div class="actions">'+button('Download draft JSON','export-draft','data-kind="'+kind+'"')+button('Open GitHub issue draft','issue-draft','data-kind="'+kind+'"','secondary')+'</div>','wide')}
function issueDraft(kind,data){const name=kind[0].toUpperCase()+kind.slice(1),title='['+name+' Submission] '+(data.name||data.displayName||data.appId||''),body='```json\n'+JSON.stringify(data,null,2)+'\n```';const url=REPO+'/issues/new?title='+encodeURIComponent(title)+'&body='+encodeURIComponent(body);if(url.length>7500){exportJSON('CloverStore-'+kind+'-submission.json',data);toast('Draft is too long for a URL. JSON downloaded; paste it into a GitHub issue.');return}downloadLink(url);closeModal()}
function routeKey(){return state.detail?'app:'+state.detail:state.developer?'developer:'+state.developer:state.collection?'collection:'+state.collection:state.tab}
function rememberPosition(){state.positions[routeKey()]=$('#main').scrollTop}
let routeDepth=0;
function writeRoute(hash,replace=false){try{history[replace?'replaceState':'pushState']({clover:true},'',location.pathname+location.search+hash);if(!replace)routeDepth++}catch{}}
function navigate(tab){rememberPosition();if(internal.open)closeInternalBrowser(false);if($('#store-menu').open)$('#store-menu').close();state.tab=tab;state.detail=null;state.developer=null;state.collection=null;writeRoute('#tab='+encodeURIComponent(tab));$('#main').scrollTop=0;render(true);$('#main').scrollTop=state.positions[routeKey()]||0}
function openDetails(id){if(!appById(id))return;rememberPosition();state.recent=[id,...state.recent.filter(x=>x!==id)].slice(0,20);saveLocal('recent',state.recent);state.detail=id;state.developer=null;state.collection=null;state.reviewSort='registry';writeRoute('#app='+encodeURIComponent(id));$('#main').scrollTop=0;render(true)}
function openDeveloper(id){rememberPosition();state.tab='Developers';state.developer=id;state.detail=null;state.collection=null;writeRoute('#developer='+encodeURIComponent(id));$('#main').scrollTop=0;render(true)}
function openCollection(id){rememberPosition();state.tab='Discover';state.collection=id;state.detail=null;state.developer=null;writeRoute('#collection='+encodeURIComponent(id));$('#main').scrollTop=0;render(true)}
function parseRoute(){try{const hash=location.hash.slice(1),at=hash.indexOf('='),key=hash.slice(0,at),value=decodeURIComponent(hash.slice(at+1));state.detail=null;state.developer=null;state.collection=null;if(key==='app')state.detail=value;else if(key==='developer'){state.tab='Developers';state.developer=value}else if(key==='collection'){state.tab='Discover';state.collection=value}else if(key==='tab')state.tab=['Discover','Browse','Search','Library','Downloads','Settings','Developers','Updates','Compare','Inspector','Disclaimers'].includes(value)?value:'Discover'}catch{state.detail=null;state.developer=null;state.collection=null}}
function goBack(){if(routeDepth>0){routeDepth--;history.back()}else navigate('Browse')}
function currentMarkup(){if(state.detail){const a=appById(state.detail);return a?details(a):heading('Listing unavailable','This app is no longer in the published catalogue.')}if(state.developer){const d=developerById(state.developer);return d?developerPage(d):message('Profile unavailable','This developer profile is not currently published.')}if(state.collection){const c=state.collections.find(c=>c.id===state.collection);return c?collectionPage(c):message('Collection unavailable','This collection is no longer published.')}return({Discover:discover,Browse:browse,Search:searchPage,Library:library,Downloads:downloadsPage,Settings:settings,Developers:developersPage,Updates:updatesPage,Compare:comparisonPage,Inspector:inspectorPage,Disclaimers:disclosures}[state.tab]||discover)()}
function render(animate=false){const main=$('#main'),top=main.scrollTop,input=$('#search'),focused=document.activeElement===input,start=input?.selectionStart;$('#page').innerHTML=currentMarkup();$('#page').classList.toggle('enter',Boolean(animate&&prefs.motion!=='reduce'));$$('nav [data-nav]').forEach(b=>{const selected=b.dataset.nav===state.tab;b.classList.toggle('active',selected);b.setAttribute('aria-current',selected?'page':'false')});main.scrollTop=top;if(focused&&$('#search')){$('#search').focus({preventScroll:true});try{$('#search').setSelectionRange(start,start)}catch{}}updateStatus();setupStickyDownload();updateCompareBadge()}
function updateCompareBadge(){const b=$('#compare-counter');if(b){b.textContent=state.compare.length;b.hidden=!state.compare.length}}
function updateStatus(){const text=state.syncing?'Refreshing catalogue…':state.error?'Connection to catalogue unavailable · retrying':state.synced?'Synced '+new Date(state.synced).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+' · 30s refresh':'Saved catalogue · syncing live';for(const id of ['#sync-status','#mobile-sync'])if($(id))$(id).textContent=text}
function applyAppearance(){const theme=selectedTheme();prefs.theme=theme.mode;document.documentElement.dataset.theme=theme.mode;document.documentElement.dataset.wallpaper=theme.id;document.documentElement.style.setProperty('--wallpaper',theme.background);document.documentElement.dataset.accent=['violet','blue','mint','rose'].includes(prefs.accent)?prefs.accent:'violet';document.documentElement.dataset.density=prefs.density==='compact'?'compact':'comfortable';document.documentElement.dataset.motion=prefs.motion==='reduce'?'reduce':'auto';document.documentElement.style.setProperty('--text-scale',['100','110','125'].includes(String(prefs.textSize))?Number(prefs.textSize)/100:1)}
function openDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('Storage unavailable'));return}const request=indexedDB.open('clover-store-html15',1);request.onupgradeneeded=()=>request.result.createObjectStore('cache');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return dbPromise}
async function cacheRead(){try{const db=await openDB();return await new Promise(resolve=>{const r=db.transaction('cache').objectStore('cache').get('catalogue');r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null)})}catch{return null}}
async function cacheWrite(data){try{const db=await openDB();const tx=db.transaction('cache','readwrite');tx.objectStore('cache').put(data,'catalogue')}catch{}}
function connection(){const online=navigator.onLine;$('#offline').hidden=online;if(online)pumpDownloads();return online}
async function getJSON(name){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(BASE+name,{cache:'no-cache',signal:controller.signal});if(!response.ok)throw Error('Catalogue HTTP '+response.status);const text=await response.text();if(text.length>4194304)throw Error('Catalogue exceeds the safety limit');return JSON.parse(text)}finally{clearTimeout(timeout)}}
async function sync(){if(!window.CLOVER_BOOT.shown||state.syncing||document.hidden||!connection())return;state.syncing=true;updateStatus();try{const names=['registry','reviews','developers','collections','releases','announcements','catalogue'],values=await Promise.all(names.map(n=>getJSON(n+'.json'))),data=Object.fromEntries(names.map((n,i)=>[n,values[i]]));if(!Array.isArray(data.registry)||!Array.isArray(data.developers)||!Array.isArray(data.collections)||!Array.isArray(data.releases)||!Array.isArray(data.announcements)||!data.reviews||Array.isArray(data.reviews)||typeof data.reviews!=='object'||data.catalogue.schemaVersion!==2)throw Error('Unexpected catalogue format');const changed=JSON.stringify([state.apps,state.reviews,state.developers,state.collections,state.releases,state.announcements,state.manifest])!==JSON.stringify(values)||state.error;state.apps=data.registry;state.reviews=data.reviews;state.developers=data.developers;state.collections=data.collections;state.releases=data.releases;state.announcements=data.announcements;state.manifest=data.catalogue;state.synced=Date.now();state.error=false;state.syncing=false;cacheWrite(data);if(changed&&!['Settings','Disclaimers','Inspector'].includes(state.tab))render();else updateStatus()}catch(e){state.syncing=false;state.error=true;connection();updateStatus()}}
function startSync(){clearInterval(timer);if(window.CLOVER_BOOT.shown&&!document.hidden){sync();timer=setInterval(sync,30000)}}
function rememberSearch(){const q=state.query.trim();if(!q)return;state.searches=[q,...state.searches.filter(x=>x!==q)].slice(0,10);saveLocal('searches',state.searches)}
function shortcuts(){modal('A faster way around.','<dl class="facts"><div><dt>Search</dt><dd>Ctrl / ⌘ + K</dd></div><div><dt>Discover</dt><dd>Alt + 1</dd></div><div><dt>Browse</dt><dd>Alt + 2</dd></div><div><dt>Library</dt><dd>Alt + 3</dd></div><div><dt>Downloads</dt><dd>Alt + 4</dd></div><div><dt>Close dialogs</dt><dd>Escape</dd></div></dl><p>For a home-screen shortcut, host this HTML on HTTPS and use your browser’s Add to Home Screen or Create shortcut command. OS-level app shortcuts and native background features require an app package.</p>')}
function clearData(){modal('Clear Clover Store data?','<p>This removes saved apps, follows, recent activity, tracked releases, handoff links, completed download records and preferences from this browser. Active transfers remain listed. Saved files and third-party website cookies are not deleted.</p>'+button('Clear local data','confirm-clear'))}
function sourceReport(a){modal('Report a listing problem.','<p>The dedicated reporting service is not connected. You can prepare a public GitHub issue describing a broken link or incorrect listing. Do not include private information.</p>'+button('Open issue draft','open-link','data-url="'+E(REPO+'/issues/new?title='+encodeURIComponent('[Listing Report] '+a.name)+'&body='+encodeURIComponent('App: '+a.id+'\n\nDescribe the problem:\n'))+'"'))}
document.addEventListener('click',async event=>{const target=event.target.closest('[data-nav],[data-open],[data-developer],[data-collection],[data-action]');if(!target)return;if(target.disabled)return;haptic();if(target.dataset.nav){navigate(target.dataset.nav);return}if(target.dataset.open){openDetails(target.dataset.open);return}if(target.dataset.developer){openDeveloper(target.dataset.developer);return}if(target.dataset.collection){openCollection(target.dataset.collection);return}const id=target.dataset.id,app=appById(id),d=state.downloads.find(d=>d.id===id);switch(target.dataset.action){
case'explore':openDetails(id);break;
case'back':goBack();break;
case'back-profile':navigate('Developers');break;
case'favorite':if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);saveLocal('favorites',[...state.favorites]);render();break;
case'follow':if(state.follows.has(id))state.follows.delete(id);else state.follows.add(id);saveLocal('follows',[...state.follows]);render();break;
case'filter':if(['category','scope','searchKind'].includes(target.dataset.key)){state[target.dataset.key]=target.dataset.value;render()}break;
case'reset-filters':state.category='All';state.scope='All devices';state.publisher='All publishers';state.sort='Featured';render();break;
case'compare-add':compareAdd(id);break;
case'share':if(app)share(app.name+'\n'+shareURL('app',id));break;
case'share-developer':share(shareURL('developer',id));break;
case'qr':qrDialog('app',id);break;
case'copy':share(target.dataset.value);break;
case'sync':sync();break;
case'download':if(app)downloadOptions(app,target.dataset.platform||platform());break;
case'enqueue':if(app)enqueue(app,target.dataset.platform);break;
case'schedule':modal('Save it for later.','<p>Downloads start only while this page remains open and any connection/charging conditions are met.</p><label class="setting-field">Start after<input id="schedule-time" type="datetime-local" required></label>'+button('Add to schedule','schedule-confirm','data-id="'+E(id)+'" data-platform="'+E(target.dataset.platform)+'"'));break;
case'schedule-confirm':{const time=Date.parse($('#schedule-time').value);if(!Number.isFinite(time)||time<=Date.now()){toast('Choose a future date and time.');break}if(app)enqueue(app,target.dataset.platform,time);break}
case'cancel':if(d){if(controllers.has(id))controllers.get(id).abort();else{d.status='Cancelled';refreshDownloads()}}break;
case'queue-up':{const i=state.downloads.findIndex(x=>x.id===id);if(i>0){[state.downloads[i-1],state.downloads[i]]=[state.downloads[i],state.downloads[i-1]];refreshDownloads()}break}
case'queue-now':if(d){d.notBefore=0;refreshDownloads();pumpDownloads()}break;
case'save-download':if(d)saveDownload(d);break;
case'direct-download':if(d)directDownload(d);break;
case'retry-download':if(d){d.status='Queued';d.done=0;d.reason='';d.notBefore=0;refreshDownloads();pumpDownloads()}break;
case'open-link':if(httpsURL(target.dataset.url)){downloadLink(httpsURL(target.dataset.url));closeModal()}break;
case'clear-downloads':state.downloads=state.downloads.filter(d=>['Queued','Downloading','Checking'].includes(d.status));for(const[id,url]of fileURLs)if(!state.downloads.some(d=>d.id===id)){URL.revokeObjectURL(url);fileURLs.delete(id);fileBlobs.delete(id)}persistDownloads();render();toast('Completed history cleared. Saved files were kept.');break;
case'watch':if(app)watchApp(app);break;
case'unwatch':delete state.watch[id];saveLocal('watch',state.watch);render();break;
case'handoff':if(app){const item=availableDownloads(app).find(d=>d.key===target.dataset.platform);if(item){state.handoff.unshift({name:app.name,appId:app.id,platform:item.key,url:item.url});state.handoff=state.handoff.slice(0,50);saveLocal('handoff',state.handoff);toast('Link saved in Library. Device pairing is not connected.')}}break;
case'handoff-remove':state.handoff.splice(Number(target.dataset.index),1);saveLocal('handoff',state.handoff);render();break;
case'export-library':exportLibrary();break;
case'import-library':$('#library-file').click();break;
case'clear-recent':state.recent=[];state.searches=[];saveLocal('recent',[]);saveLocal('searches',[]);render();break;
case'disclaimers':navigate('Disclaimers');break;
case'whatsnew':whatsNew();break;
case'new-dismiss':saveLocal('seenVersion',VERSION);closeModal();navigate('Discover');break;
case'shortcuts':shortcuts();break;
case'clear-data':clearData();break;
case'confirm-clear':{for(const key of ['favorites','follows','recent','searches','watch','handoff','preferences']){try{localStorage.removeItem('clover-html-v5:'+key)}catch{}}state.favorites.clear();state.follows.clear();state.recent=[];state.searches=[];state.watch={};state.handoff=[];state.downloads=state.downloads.filter(d=>['Queued','Downloading','Checking'].includes(d.status));Object.assign(prefs,defaults);persistDownloads();try{const db=await openDB();db.transaction('cache','readwrite').objectStore('cache').clear()}catch{}applyAppearance();closeModal();render();toast('Clover Store local data cleared.');break}
case'diagnostics':share(JSON.stringify({app:'Clover Store HTML '+VERSION,platform:platform(),apps:allApps().length,lastSync:state.synced?new Date(state.synced).toISOString():null,online:navigator.onLine,services:state.manifest.services},null,2));break;
case'select-theme':if(THEMES.some(t=>t.id===target.dataset.themeId)){prefs.wallpaper=target.dataset.themeId;saveLocal('preferences',prefs);applyAppearance();render();document.querySelector('[data-theme-id="'+prefs.wallpaper+'"]')?.focus({preventScroll:true});toast(selectedTheme().name+' applied.')}break;
case'notifications':await requestNotifications();break;
case'test-notification':testNotification();break;
case'choose-download-folder':await chooseDownloadFolder();break;
case'forget-download-folder':downloadFolder=null;render();toast('Download folder forgotten.');break;
case'save-all-ready':await saveAllReady();break;
case'expand-description':$('#app-description').classList.toggle('expanded');target.textContent=$('#app-description').classList.contains('expanded')?'Show less':'Read more';break;
case'screenshot':{const shots=screenshotURLs(app);const index=Number(target.dataset.index);modal(app.name+' · '+(index+1)+' / '+shots.length,'<img class="lightbox-image" src="'+E(shots[index])+'" alt="'+E(app.name)+' screenshot"><div class="actions">'+(index?button('Previous','screenshot','data-id="'+E(id)+'" data-index="'+(index-1)+'"','secondary'):'')+(index<shots.length-1?button('Next','screenshot','data-id="'+E(id)+'" data-index="'+(index+1)+'"','secondary'):'')+'</div>','lightbox');break}
case'search-term':state.query=target.dataset.value;render();break;
case'review':submissionDraft('review',id);break;
case'review-draft':{const data={appId:id,name:$('#draft-name').value.trim(),rating:Number($('#draft-rating').value),comment:$('#draft-comment').value.trim()};if(!data.name||!data.comment){toast('Add a display name and review.');break}issueDraft('review',data);break}
case'report':if(app)sourceReport(app);break;
case'developer-draft':submissionDraft('developer');break;
case'app-draft':submissionDraft('app');break;
case'export-draft':case'issue-draft':try{const data=JSON.parse($('#draft-json').value);if(!data||typeof data!=='object'||Array.isArray(data))throw Error();if(target.dataset.action==='export-draft')exportJSON('CloverStore-'+target.dataset.kind+'-draft.json',data);else issueDraft(target.dataset.kind,data)}catch{toast('Enter a valid JSON object.')}break;
}});
document.addEventListener('input',event=>{if(event.target.id==='search'){state.query=event.target.value;if($('#results'))$('#results').innerHTML=searchResults()}if(event.target.hasAttribute('data-public-url')){const text=event.target.value.trim();prefs.publicUrl=text?httpsURL(text):'';saveLocal('preferences',prefs)}});
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='device-platform'){saveLocal('platform',el.value);render()}if(el.id==='review-sort'){state.reviewSort=el.value;render()}if(el.dataset.state&&['sort','publisher'].includes(el.dataset.state)){state[el.dataset.state]=el.value;render()}if(el.dataset.channel){state.channels[el.dataset.channel]=el.value;render()}if(el.dataset.pref){prefs[el.dataset.pref]=el.type==='checkbox'?el.checked:el.value;saveLocal('preferences',prefs);applyAppearance();if(prefs.chargingOnly&&navigator.getBattery)navigator.getBattery().then(b=>battery=b).catch(()=>{});pumpDownloads()}if(el.id==='library-file'&&el.files[0]){await importLibrary(el.files[0]);el.value=''}if(el.id==='apk-file'&&el.files[0]){const file=el.files[0];inspectionFile=file;$('#apk-results').innerHTML='<p class="muted">Inspecting locally…</p>';try{if(file.size>APKInspector.MAX_FILE)throw Error('Choose an APK smaller than 128 MB.');inspection=await APKInspector.inspect(await file.arrayBuffer());if($('#apk-results'))$('#apk-results').innerHTML=inspectionMarkup(inspection)}catch(e){inspection=null;if($('#apk-results'))$('#apk-results').innerHTML=message('Unable to inspect this APK',e.message)}}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();navigate('Search');$('#search')?.focus()}if(event.altKey&&['1','2','3','4'].includes(event.key)){event.preventDefault();navigate(['Discover','Browse','Library','Downloads'][Number(event.key)-1])}if(event.key==='Enter'&&event.target.id==='search')rememberSearch()});
document.addEventListener('focusout',event=>{if(event.target.id==='search')rememberSearch()});
document.addEventListener('error',event=>{if(event.target.matches?.('.icon-wrap img')){event.target.style.display='none';event.target.parentElement.classList.add('failed')}if(event.target.matches?.('.developer-avatar img')){const parent=event.target.parentElement;parent.textContent=initials(event.target.alt.replace(/ icon$/,''))}},true);
window.addEventListener('popstate',()=>{parseRoute();render(true);$('#main').scrollTop=state.positions[routeKey()]||0});
window.addEventListener('offline',connection);window.addEventListener('online',()=>{connection();sync()});document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInterval(timer);else{startSync();pumpDownloads()}});
window.addEventListener('pagehide',()=>{clearInterval(timer);for(const c of controllers.values())c.abort();persistDownloads()});

const internal={open:false,url:"",history:[],tracked:false,loading:false,loadTimer:null,returnFocus:null};
function updateStickyDownload(visible){const sticky=$('#mobile-download');if(sticky)sticky.hidden=!visible;}
function setupStickyDownload(){
 if(detailObserver){detailObserver.disconnect();detailObserver=null}
 const sticky=$('#mobile-download');sticky.hidden=true;const app=appById(state.detail),download=app?primaryDownload(app):null;
 if(!app||!download)return;
 sticky.innerHTML='<div class="sticky-name"><strong>'+escapeHTML(app.name)+'</strong><small>For '+escapeHTML(platformLabel(download.key))+'</small></div>'+button('↓ Download','download','data-id="'+escapeHTML(app.id)+'" data-platform="'+escapeHTML(download.key)+'"');
 const source=$('.detail-actions > [data-action="download"]');
 if(source&&'IntersectionObserver' in window){detailObserver=new IntersectionObserver(entries=>updateStickyDownload(!entries[0].isIntersecting&&$('#main').scrollTop>60),{root:$('#main'),threshold:0});detailObserver.observe(source)}
}
function openStoreMenu(){
 const select=$('#sheet-platform');select.value=readLocal('platform','auto');
 $('#detected-platform').textContent='Detected device: '+platformLabel(detectPlatform());
 $('#store-menu').showModal();
}
function showAddressDialog(prefill=''){
 $('#address-input').value=prefill;$('#address-error').hidden=true;
 $('#address-help').textContent=internal.open
 ? 'Opened address: '+internal.url+'. HTML cannot read addresses or history inside unrelated websites after navigation. Open in your regular browser for full navigation.'
 : 'Enter a secure website address. Websites open inside Clover Store when they permit embedding.';
 $('#address-dialog').showModal();$('#address-input').focus();
}
function permittedBrowserURL(input){
 let text=String(input||'').trim();if(!text)return '';
 if(!/^[a-z][a-z0-9+.-]*:/i.test(text))text='https://'+text;
 try{const u=new URL(text);if(u.username||u.password)return '';if(u.protocol==='https:')return u.href;if(u.origin===location.origin&&u.protocol==='http:')return u.href;return ''}catch{return ''}
}
function appWebsites(a){
 const values=[['Website',a.website||a.homepage||a.websiteUrl],['Support',a.supportUrl||a.support_url],['Privacy',a.privacyPolicy||a.privacy_url]];
 return values.filter(([,url])=>typeof url==='string'&&httpsURL(url)).map(([label,url])=>({label,url:httpsURL(url)}));
}

function setBrowserBusy(busy){
 internal.loading=busy;
 $('#browser-reload').classList.toggle('loading',busy);
 $('#browser-reload').setAttribute('aria-label',busy?'Website is loading; reload':'Reload website');
 $('#browser-progress').hidden=!busy;
}
function updateBrowserAddress(){
 const url=new URL(internal.url);
 $('#browser-domain').textContent=url.host;
 $('#browser-address-type').textContent=internal.tracked?'Current page':'Opened website';
 $('#browser-address').title=internal.url;
 $('#browser-external').href=internal.url;
 $('#browser-status').textContent=internal.tracked?'Browsing in Clover Store':'Page not showing? Some websites block embedding.';
}
function openInternalBrowser(value,replace=false){
 const url=permittedBrowserURL(value);if(!url){toast('Enter a valid HTTPS website address.');return}
 if(prefs.externalWebsites&&!replace){window.open(url,'_blank','noopener,noreferrer');return}
 if(!internal.open){internal.returnFocus=document.activeElement;internal.history=[]}
 internal.open=true;internal.tracked=false;internal.url=url;
 if(replace&&internal.history.length)internal.history[internal.history.length-1]=url;
 else if(internal.history.at(-1)!==url)internal.history.push(url);
 $('#internal-browser').hidden=false;document.body.classList.add('browser-open');
 $('#browser-menu').hidden=true;$('#browser-menu-button').setAttribute('aria-expanded','false');
 updateBrowserAddress();setBrowserBusy(true);
 $('#website-frame').src=url;
 clearTimeout(internal.loadTimer);
 internal.loadTimer=setTimeout(()=>{setBrowserBusy(false);$('#browser-status').textContent='If this page is blank or blocked, open it in your browser.';},18000);
 $('#browser-address').focus();
}
function closeInternalBrowser(restore=true){
 if(!internal.open)return;internal.open=false;
 clearTimeout(internal.loadTimer);$('#internal-browser').hidden=true;
 $('#browser-menu').hidden=true;$('#browser-menu-button').setAttribute('aria-expanded','false');
 document.body.classList.remove('browser-open');$('#website-frame').src='about:blank';setBrowserBusy(false);
 if(restore){internal.returnFocus?.focus?.({preventScroll:true});setupStickyDownload();}
}
function browserBack(){
 if(internal.history.length>1){internal.history.pop();const prev=internal.history.at(-1);internal.replaceNext=true;openInternalBrowser(prev,true)}
 else closeInternalBrowser();
}
$('#website-frame').addEventListener('load',()=>{
 if(!internal.open)return;clearTimeout(internal.loadTimer);setBrowserBusy(false);
 try{
  const href=$('#website-frame').contentWindow.location.href;
  if(href==='about:blank')return;
  const safe=permittedBrowserURL(href);
  if(safe){internal.url=safe;internal.tracked=true;if(internal.history.at(-1)!==safe)internal.history.push(safe)}
 }catch{internal.tracked=false}
 updateBrowserAddress();
});
$('#browser-address').onclick=()=>showAddressDialog(internal.url);
$('#browser-reload').onclick=()=>{
 if(!internal.open)return;setBrowserBusy(true);
 try{$('#website-frame').contentWindow.location.reload()}catch{$('#website-frame').src=internal.url}
 clearTimeout(internal.loadTimer);internal.loadTimer=setTimeout(()=>setBrowserBusy(false),18000);
};
$('#browser-menu-button').onclick=()=>{
 const menu=$('#browser-menu');menu.hidden=!menu.hidden;
 $('#browser-menu-button').setAttribute('aria-expanded',String(!menu.hidden));
 if(!menu.hidden)menu.querySelector('button')?.focus();
};
$('#browser-back').onclick=browserBack;
$('#address-form').addEventListener('submit',e=>{
 e.preventDefault();const url=permittedBrowserURL($('#address-input').value);
 if(!url){$('#address-error').textContent='Please enter a valid HTTPS address.';$('#address-error').hidden=false;return}
 $('#address-dialog').close();openInternalBrowser(url);
});
$('#store-menu-button').onclick=openStoreMenu;
document.addEventListener('click',e=>{
 const close=e.target.closest('[data-close-dialog]');if(close){$('#'+close.dataset.closeDialog).close();return}
 const button=e.target.closest('[data-action="internal-browser"],[data-action="open-address"]');
 if(button){if(button.dataset.action==='open-address')showAddressDialog();else openInternalBrowser(button.dataset.url)}
 const menu=$('#browser-menu');
 if(internal.open&&!menu.hidden&&!e.target.closest('#browser-menu,#browser-menu-button')){menu.hidden=true;$('#browser-menu-button').setAttribute('aria-expanded','false')}
});
document.addEventListener('change',e=>{
 if(e.target.id==='sheet-platform'){saveLocal('platform',e.target.value);$('#device-platform').value=e.target.value;render()}
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&internal.open&&!$('#address-dialog').open){
  if(!$('#browser-menu').hidden){$('#browser-menu').hidden=true;$('#browser-menu-button').setAttribute('aria-expanded','false');$('#browser-menu-button').focus();}
  else closeInternalBrowser();
 }
});

function initialiseNavigation(){
 const config=window.CLOVER_BOOT.navigation;
 const item=name=>'<button data-nav="'+E(name)+'">'+svg(name)+'<span>'+E(name)+'</span>'+(name==='Compare'?'<small id="compare-counter" hidden></small>':'')+'</button>';
 document.querySelector('.sidebar nav').innerHTML=config.sidebar.map(name=>item(name).replace(svg(name),'<span class="nav-symbol">'+svg(name)+'</span>')).join('');
 $('#store-menu .sheet-links').innerHTML=config.menu.map(item).join('');
 const mobile=document.createElement('nav');mobile.className='mobile-nav';mobile.setAttribute('aria-label','Mobile navigation');mobile.innerHTML=config.mobile.map(item).join('');document.body.append(mobile);
 $('#browser-menu').innerHTML=config.browser.map(item).join('')+'<button id="browser-back" class="go-back">← Go Back</button>';
 $('#browser-back').onclick=browserBack;
}
initialiseNavigation();applyAppearance();parseRoute();$('#device-platform').value=readLocal('platform','auto');
document.querySelector('.top-search input').addEventListener('input',event=>{state.query=event.target.value;if(state.tab!=='Search'||state.detail||state.developer){navigate('Search');$('#search')?.focus()}if($('#search'))$('#search').value=state.query;if($('#results'))$('#results').innerHTML=searchResults()});
$('#retry-connection').onclick=()=>{if(connection())sync()};
render();connection();cacheRead().then(data=>{if(data&&!state.synced&&Array.isArray(data.registry)&&Array.isArray(data.developers)){Object.assign(state,{apps:data.registry,reviews:data.reviews||{},developers:data.developers,collections:data.collections||[],releases:data.releases||[],announcements:data.announcements||[],manifest:data.catalogue||state.manifest});render()}});window.addEventListener('clover:shown',startSync,{once:true});
setInterval(()=>{pumpDownloads();if(state.tab==='Downloads'&&state.downloads.some(d=>d.status==='Queued'))refreshDownloads()},1500);
window.CLOVER_BOOT.ready=true;
if(prefs.chargingOnly&&navigator.getBattery)navigator.getBattery().then(b=>battery=b).catch(()=>{});
